From 40fe5a1631e0581988116d231991f628148ea29b Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 19:24:16 +0100
Subject: [PATCH] containments/desktop: Add a Show Icons toggle to the Icons
 menu

There was no quick way to hide the files and folders on the desktop: the
only option was turning them off entirely in the desktop settings. Add a
checkable Show Icons entry to the desktop's Icons menu that hides them.

BUG: 495205
---
 .../desktop/package/contents/config/main.xml  |  4 +++
 .../package/contents/ui/FolderViewLayer.qml   | 12 +++++++
 .../plugins/folder/viewpropertiesmenu.cpp     | 33 +++++++++++++++++++
 .../plugins/folder/viewpropertiesmenu.h       | 11 +++++++
 4 files changed, 60 insertions(+)

diff --git a/containments/desktop/package/contents/config/main.xml b/containments/desktop/package/contents/config/main.xml
index 2621cac672..90aa0ee507 100644
--- a/containments/desktop/package/contents/config/main.xml
+++ b/containments/desktop/package/contents/config/main.xml
@@ -131,6 +131,10 @@
       <label>List of MIME types to filter by.</label>
       <default>all/all</default>
     </entry>
+    <entry name="iconsVisible" type="Bool">
+      <label>Show the icons of files and folders on the desktop.</label>
+      <default>true</default>
+    </entry>
     <entry name="showHiddenFiles" type="Bool">
       <label>Show hidden files.</label>
       <default>false</default>
diff --git a/containments/desktop/package/contents/ui/FolderViewLayer.qml b/containments/desktop/package/contents/ui/FolderViewLayer.qml
index 02c7491b36..fb8b6dcbf5 100644
--- a/containments/desktop/package/contents/ui/FolderViewLayer.qml
+++ b/containments/desktop/package/contents/ui/FolderViewLayer.qml
@@ -86,6 +86,7 @@ FocusScope {

         showLayoutActions: !folderViewLayerComponent.inPanel
         showLockAction: Plasmoid.isContainment
+        showIconsVisibleAction: Plasmoid.isContainment
         showIconSizeActions: !folderViewLayerComponent.useListViewMode

         lockedEnabled: !folderViewLayerComponent.lockedByKiosk
@@ -108,6 +109,10 @@ FocusScope {
             }
         }

+        onIconsVisibleChanged: {
+            Plasmoid.configuration.iconsVisible = iconsVisible;
+        }
+
         onSortModeChanged: {
             Plasmoid.configuration.sortMode = sortMode;
         }
@@ -129,6 +134,7 @@ FocusScope {
             alignment = Plasmoid.configuration.alignment;
             previews = Plasmoid.configuration.previews;
             locked = Plasmoid.configuration.locked || folderViewLayerComponent.lockedByKiosk;
+            iconsVisible = Plasmoid.configuration.iconsVisible;
             sortMode = Plasmoid.configuration.sortMode;
             sortDesc = Plasmoid.configuration.sortDesc;
             sortDirsFirst = Plasmoid.configuration.sortDirsFirst;
@@ -182,6 +188,10 @@ FocusScope {
             viewPropertiesMenu.locked = Plasmoid.configuration.locked;
         }

+        function onIconsVisibleChanged() {
+            viewPropertiesMenu.iconsVisible = Plasmoid.configuration.iconsVisible;
+        }
+
         function onSortModeChanged() {
             folderView.sortMode = Plasmoid.configuration.sortMode;
             viewPropertiesMenu.sortMode = Plasmoid.configuration.sortMode;
@@ -209,6 +219,8 @@ FocusScope {
         anchors.right: parent.right
         anchors.bottom: parent.bottom

+        visible: !Plasmoid.isContainment || Plasmoid.configuration.iconsVisible
+
         focus: true
         isRootView: Plasmoid.isContainment
         positionerApplet: Plasmoid
diff --git a/containments/desktop/plugins/folder/viewpropertiesmenu.cpp b/containments/desktop/plugins/folder/viewpropertiesmenu.cpp
index 659fbe57ba..231987ced1 100644
--- a/containments/desktop/plugins/folder/viewpropertiesmenu.cpp
+++ b/containments/desktop/plugins/folder/viewpropertiesmenu.cpp
@@ -102,6 +102,13 @@ ViewPropertiesMenu::ViewPropertiesMenu(QObject *parent)
                                  this,
                                  &ViewPropertiesMenu::lockedChanged);
     m_locked->setCheckable(true);
+
+    m_iconsVisible = m_menu->addAction(QIcon::fromTheme(QStringLiteral("view-visible")),
+                                       i18nc("@item:inmenu show or hide all desktop icons", "Show Icons"),
+                                       this,
+                                       &ViewPropertiesMenu::iconsVisibleChanged);
+    m_iconsVisible->setCheckable(true);
+    m_iconsVisible->setChecked(true);
 }

 ViewPropertiesMenu::~ViewPropertiesMenu()
@@ -143,6 +150,20 @@ void ViewPropertiesMenu::setShowLockAction(bool show)
     }
 }

+bool ViewPropertiesMenu::showIconsVisibleAction() const
+{
+    return m_iconsVisible->isVisible();
+}
+
+void ViewPropertiesMenu::setShowIconsVisibleAction(bool show)
+{
+    if (m_iconsVisible->isVisible() != show) {
+        m_iconsVisible->setVisible(show);
+
+        Q_EMIT showIconsVisibleActionChanged();
+    }
+}
+
 bool ViewPropertiesMenu::showIconSizeActions() const
 {
     return m_iconSizeMenu->menuAction()->isVisible();
@@ -216,6 +237,18 @@ void ViewPropertiesMenu::setLocked(bool locked)
     }
 }

+bool ViewPropertiesMenu::iconsVisible() const
+{
+    return m_iconsVisible->isChecked();
+}
+
+void ViewPropertiesMenu::setIconsVisible(bool visible)
+{
+    if (m_iconsVisible->isChecked() != visible) {
+        m_iconsVisible->setChecked(visible);
+    }
+}
+
 bool ViewPropertiesMenu::lockedEnabled() const
 {
     return m_locked->isEnabled();
diff --git a/containments/desktop/plugins/folder/viewpropertiesmenu.h b/containments/desktop/plugins/folder/viewpropertiesmenu.h
index cef06f3de4..31716eb642 100644
--- a/containments/desktop/plugins/folder/viewpropertiesmenu.h
+++ b/containments/desktop/plugins/folder/viewpropertiesmenu.h
@@ -23,11 +23,13 @@ class ViewPropertiesMenu : public QObject
     Q_PROPERTY(bool showLayoutActions READ showLayoutActions WRITE setShowLayoutActions NOTIFY showLayoutActionsChanged)
     Q_PROPERTY(bool showLockAction READ showLockAction WRITE setShowLockAction NOTIFY showLockActionChanged)
     Q_PROPERTY(bool showIconSizeActions READ showIconSizeActions WRITE setShowIconSizeActions NOTIFY showIconSizeActionsChanged)
+    Q_PROPERTY(bool showIconsVisibleAction READ showIconsVisibleAction WRITE setShowIconsVisibleAction NOTIFY showIconsVisibleActionChanged)

     Q_PROPERTY(int arrangement READ arrangement WRITE setArrangement NOTIFY arrangementChanged)
     Q_PROPERTY(int alignment READ alignment WRITE setAlignment NOTIFY alignmentChanged)
     Q_PROPERTY(bool previews READ previews WRITE setPreviews NOTIFY previewsChanged)
     Q_PROPERTY(bool locked READ locked WRITE setLocked NOTIFY lockedChanged)
+    Q_PROPERTY(bool iconsVisible READ iconsVisible WRITE setIconsVisible NOTIFY iconsVisibleChanged)
     Q_PROPERTY(bool lockedEnabled READ lockedEnabled WRITE setLockedEnabled NOTIFY lockedEnabledChanged)
     Q_PROPERTY(int sortMode READ sortMode WRITE setSortMode NOTIFY sortModeChanged)
     Q_PROPERTY(bool sortDesc READ sortDesc WRITE setSortDesc NOTIFY sortDescChanged)
@@ -49,6 +51,9 @@ public:
     bool showIconSizeActions() const;
     void setShowIconSizeActions(bool show);

+    bool showIconsVisibleAction() const;
+    void setShowIconsVisibleAction(bool show);
+
     int arrangement() const;
     void setArrangement(int arrangement);

@@ -61,6 +66,9 @@ public:
     bool locked() const;
     void setLocked(bool locked);

+    bool iconsVisible() const;
+    void setIconsVisible(bool visible);
+
     bool lockedEnabled() const;
     void setLockedEnabled(bool lockedEnabled);

@@ -80,10 +88,12 @@ Q_SIGNALS:
     void showLayoutActionsChanged() const;
     void showLockActionChanged() const;
     void showIconSizeActionsChanged();
+    void showIconsVisibleActionChanged();
     void arrangementChanged() const;
     void alignmentChanged() const;
     void previewsChanged() const;
     void lockedChanged() const;
+    void iconsVisibleChanged() const;
     void lockedEnabledChanged() const;
     void sortModeChanged() const;
     void sortDescChanged() const;
@@ -103,4 +113,5 @@ private:
     QAction *m_sortDirsFirst;
     QAction *m_previews;
     QAction *m_locked;
+    QAction *m_iconsVisible;
 };
-- 
